import { useEffect, useRef, useState } from 'react';
import './App.css';

import SetupScreen from './components/SetupScreen';
import TreatmentScreen from './components/TreatmentScreen';
import { useBleDevice } from './context/BleProvider';
import { useTreatment } from './context/TreatmentProvider';

import TopBar from './components/TopBar';

import ManualHeadRendering from './test/ManualHeadRendering';
import ResearchScreenTestPanel from './test/ResearchScreenTestPanel';

// Mantine UI imports
import {
  AppShell,
  Button,
  Modal,
  useMantineTheme,
} from '@mantine/core';

import StateMachineTestPanel from './test/StateMachineTestPanel';
import CalibrationScreen from './components/CalibrationScreen';
import ResearchScreen from './components/ResearchScreen';
import GyroscopeCalibrationScreen from './components/GyroscopeCalibrationScreen';
import GuidedCalibrationScreen from './components/GuidedCalibrationScreen';
import HeadCanalAlignmentTestPanel from './test/HeadCanalAlignmentTestPanel';
import { TreatmentStage } from './types/treatmentTypes';
import AssetLoadingGate from './components/AssetLoadingGate';
import { AppSoundProvider } from './context/AppSoundProvider';

type Screen = 'setup' | 'calibrate' | 'calibration' | 'treatment' | 'research';

const POWER_DOWN_BYTE = 0xf0;
const POWER_DOWN_TEXT = '0xF0';
const BLE_BUTTON_PROGRESS_COMMAND = 1;
const BLE_BUTTON_RETURN_COMMAND = 2;

function isPowerDownNotification(value: DataView): boolean {
  const bytes = new Uint8Array(value.buffer, value.byteOffset, value.byteLength);

  if (bytes.some((byte) => byte === POWER_DOWN_BYTE)) {
    return true;
  }

  const text = new TextDecoder().decode(bytes).trim();
  return text.toUpperCase().includes(POWER_DOWN_TEXT.toUpperCase());
}




function App(): JSX.Element { 

  const ble = useBleDevice();
  const treatment = useTreatment();
  const treatmentDispatch = treatment.dispatch;

  const [screen, setScreen] = useState<Screen>('setup');
  const [selectedCanals, setSelectedCanals] = useState<string[]>([]);

  const testMode = false; // Set to true to enable test mode (bypasses setup and calibration)
  // To control calibration popup
  const [calibrationOpen, setCalibrationOpen] = useState(false);
  const [powerDownNotificationOpen, setPowerDownNotificationOpen] = useState(false);
  const [calibrationStartRequestId, setCalibrationStartRequestId] = useState<number | null>(null);
  const [dixHallpikeModalOpened, setDixHallpikeModalOpened] = useState(false);
  const [dixHallpikeBackArmed, setDixHallpikeBackArmed] = useState(false);
  const lastProcessedButtonMessageIdRef = useRef<number | null>(null);
  const lastDixHallpikeBackPressRef = useRef<number | null>(null);
  const dixHallpikeBackTimerRef = useRef<number | null>(null);

  useEffect(() => {
    const reachedDixHallpikeDecision =
      screen === 'treatment' &&
      treatment.state.stage === TreatmentStage.STAGE_1 &&
      treatment.state.stageProgress >= 1;

    if (reachedDixHallpikeDecision) {
      setDixHallpikeModalOpened(true);
    }
  }, [screen, treatment.state.stage, treatment.state.stageProgress]);

  useEffect(() => () => {
    if (dixHallpikeBackTimerRef.current !== null) {
      window.clearTimeout(dixHallpikeBackTimerRef.current);
    }
  }, []);

  useEffect(() => {
    const message = ble.latestButtonMessage;

    if (!message || lastProcessedButtonMessageIdRef.current === message.id) {
      return;
    }

    // Consume every button message immediately so a press made on another
    // screen cannot be replayed when the treatment screen is opened later.
    lastProcessedButtonMessageIdRef.current = message.id;

    if (isPowerDownNotification(message.data)) {
      const isCompletedTreatment = screen === 'treatment'
        && treatment.state.stage === TreatmentStage.COMPLETE;

      if (!isCompletedTreatment) {
        setPowerDownNotificationOpen(true);
      }
      return;
    }

    if (message.data.byteLength < 1) {
      return;
    }

    const command = message.data.byteLength >= 2
      ? message.data.getUint16(0, true)
      : message.data.getUint8(0);

    const treatmentNavigationEnabled = screen === 'treatment'
      && treatment.state.stage !== TreatmentStage.COMPLETE;

    if ((screen === 'calibrate' || screen === 'calibration') && command === BLE_BUTTON_PROGRESS_COMMAND) {
      setCalibrationStartRequestId(message.id);
    } else if (treatmentNavigationEnabled && command === BLE_BUTTON_PROGRESS_COMMAND) {
      handleTreatmentProgressRequest();
    } else if (treatmentNavigationEnabled && command === BLE_BUTTON_RETURN_COMMAND) {
      handleTreatmentBackRequest();
    }
  }, [
    ble.latestButtonMessage,
    dixHallpikeModalOpened,
    screen,
    treatment.state.stage,
    treatmentDispatch,
  ]);

 
  // Mantine theming
  const theme = useMantineTheme();

  async function handleSystemReset() {
    closeDixHallpikeDecision();
    setCalibrationOpen(false);
    setPowerDownNotificationOpen(false);
    setSelectedCanals([]);
    await ble.disconnect();
    lastProcessedButtonMessageIdRef.current = null;
    treatment.resetTreatment();
    treatment.clearGyroscopeOffsets();
    setScreen('setup');
  }

  async function handleReconnect() {
    const connected = await ble.connect();

    if (connected) {
      setPowerDownNotificationOpen(false);
    }
  }

  function handleSwitchToOppositeEar() {
    closeDixHallpikeDecision();
    if (!treatment.switchToOppositeEarWithoutRemount()) return;

    if (treatment.isRecording) {
      treatment.stopRecording();
    }
    setCalibrationStartRequestId(null);
    setScreen('calibrate');
  }

  function closeDixHallpikeDecision() {
    setDixHallpikeModalOpened(false);
    setDixHallpikeBackArmed(false);
    lastDixHallpikeBackPressRef.current = null;
    if (dixHallpikeBackTimerRef.current !== null) {
      window.clearTimeout(dixHallpikeBackTimerRef.current);
      dixHallpikeBackTimerRef.current = null;
    }
  }

  function continueFromDixHallpike() {
    closeDixHallpikeDecision();
    treatmentDispatch({ type: 'PROGRESS' });
  }

  function handleTreatmentProgressRequest() {
    if (treatment.state.stage === TreatmentStage.STAGE_1) {
      if (dixHallpikeModalOpened) {
        continueFromDixHallpike();
        return;
      }
      setDixHallpikeModalOpened(true);
      return;
    }
    treatmentDispatch({ type: 'PROGRESS' });
  }

  function handleTreatmentBackRequest() {
    if (!dixHallpikeModalOpened) {
      if (treatment.state.stage === TreatmentStage.STAGE_1) {
        setCalibrationStartRequestId(null);
        setScreen('calibrate');
        return;
      }
      treatmentDispatch({ type: 'RETURN_TO_PREVIOUS_STAGE' });
      return;
    }

    const now = Date.now();
    const previousPress = lastDixHallpikeBackPressRef.current;

    if (previousPress !== null && now - previousPress <= 1500) {
      handleSwitchToOppositeEar();
      return;
    }

    lastDixHallpikeBackPressRef.current = now;
    setDixHallpikeBackArmed(true);
    if (dixHallpikeBackTimerRef.current !== null) {
      window.clearTimeout(dixHallpikeBackTimerRef.current);
    }
    dixHallpikeBackTimerRef.current = window.setTimeout(() => {
      lastDixHallpikeBackPressRef.current = null;
      setDixHallpikeBackArmed(false);
      dixHallpikeBackTimerRef.current = null;
    }, 1500);
  }

  return (
    <AppSoundProvider>
    <AssetLoadingGate>
      <AppShell
        header={{ height: 60 }}
        // footer={{ height: 40 }}
        padding="md"
        style={{height: '100vh', overflow: 'hidden'}}
      >

      <AppShell.Header style={{
          backgroundColor: theme.colors.blue[6],
          color: theme.white,
        }}>
        <TopBar
          setScreen={setScreen}
          setCalibrationOpen={setCalibrationOpen}
          onReset={handleSystemReset}
          showTimerSlider={false} //{screen === 'calibrate' || screen === 'treatment'}
          showReconnectButton={screen !== 'setup'}
        />

      </AppShell.Header>

      <Modal
        opened={calibrationOpen}
        onClose={() => setCalibrationOpen(false)}
        title="Gyroscope calibration"
        centered
      >
        <GyroscopeCalibrationScreen onComplete={() => setCalibrationOpen(false)} />
    </Modal>

      <Modal
        opened={powerDownNotificationOpen}
        onClose={() => setPowerDownNotificationOpen(false)}
        title="Device powering down"
        centered
      >
        <p>
          The Bluetooth device is powering down. Turn it back on, then reconnect to
          continue without losing the current treatment selections or progress.
        </p>
        <Button
          fullWidth
          loading={ble.connecting}
          disabled={ble.connected}
          onClick={handleReconnect}
        >
          {ble.connected ? 'Waiting for device to power down' : 'Reconnect device'}
        </Button>
        {ble.error && (
          <p style={{ color: 'var(--mantine-color-red-7)' }} role="alert">
            {ble.error}
          </p>
        )}
      </Modal>
      

    <AppShell.Main
      style={{
        minHeight: 'calc(100vh - 60px)', // full height minus header
        // maxHeight: '60vh',
        overflow: 'hidden',
        display: 'block',
        backgroundColor: theme.colors.gray[0],
        justifyContent: 'center',
        alignItems: 'center',
      }}>

      {
      testMode ? (
          // <ResearchScreenTestPanel
          //   bleStatus={ble.connected ? 'connected' : 'disconnected'}
          //   deviceName={ble.deviceName}
          //   bleError={ble.error}
          //   onConnect={ble.connect}
          //   onDisconnect={ble.disconnect}
          // />
          <HeadCanalAlignmentTestPanel />
        
      ) : screen === 'setup' ? (
        <SetupScreen
          bleStatus={
            ble.connected
              ? 'connected'
              : ble.connecting
                ? 'connecting'
                : ble.error
                  ? 'error'
                  : 'disconnected'
          }
          deviceName={ble.deviceName}
          batteryLevel={ble.batteryLevel}
          bleError={ble.error}
          onConnect={ble.connect}
          onDisconnect={ble.disconnect}
          onContinue={() => setScreen('calibrate')}
        />
      ) : screen === 'research' ? (
        <ResearchScreen
          onBack={() => setScreen('calibrate')}
        />
      ) :
      
      screen === 'treatment' ? (
        <TreatmentScreen
          onBack={() => setScreen('calibrate')}
          deviceConnected={ble.connected}
          onFinish={handleSystemReset}
          onSwitchToOppositeEar={handleSwitchToOppositeEar}
          onRequestProgress={handleTreatmentProgressRequest}
          onContinueFromDixHallpike={continueFromDixHallpike}
          dixHallpikeModalOpened={dixHallpikeModalOpened}
          dixHallpikeBackArmed={dixHallpikeBackArmed}
        />
      ) : screen === 'calibration' ? (
          <GuidedCalibrationScreen
            onBack={() => {
              setCalibrationStartRequestId(null);
              setScreen('calibrate');
            }}
            onComplete={() => {
              setCalibrationStartRequestId(null);
              setScreen('treatment');
            }}
            startRequestId={calibrationStartRequestId}
            onStartRequestHandled={() => setCalibrationStartRequestId(null)}
        />
      ) : (
          <CalibrationScreen
            onBack={() => {
              setCalibrationStartRequestId(null);
              setScreen('setup');
            }}
            onContinue={() => {
              setCalibrationStartRequestId(null);
              setScreen('calibration');
            }}
            startRequestId={calibrationStartRequestId}
            onStartRequestHandled={() => setCalibrationStartRequestId(null)}
          />
      )}
    </AppShell.Main>

    {/* <AppShell.Footer style={{
          backgroundColor: theme.colors.blue[6],
          color: theme.white,
        }}>
          <StatusBar />
    </AppShell.Footer> */}

    </AppShell>
    </AssetLoadingGate>
    </AppSoundProvider>
    
  );
}

export default App;
